class Solution {
    // Function to sort a k-sorted array using min heap
    sortNearlySortedArray(arr, k) {
        // Custom min heap using array + sort
        let heap = [];

        // Result array
        const result = [];

        // Insert first k+1 elements into heap
        for (let i = 0; i <= k && i < arr.length; i++) {
            heap.push(arr[i]);
        }

        // Sort to simulate heap
        heap.sort((a, b) => a - b);

        // Process remaining elements
        for (let i = k + 1; i < arr.length; i++) {
            result.push(heap.shift()); // Remove smallest
            heap.push(arr[i]);
            heap.sort((a, b) => a - b); // Re-sort
        }

        // Add remaining heap elements
        while (heap.length > 0) {
            result.push(heap.shift());
        }

        return result;
    }
}

